const official_schedule = [
  {event_id:'FRI', start_time:'19:00', venue:'Grand Cinema', ticket_url:'https://example.org/friday'},
  {event_id:'SAT', start_time:'18:00', venue:'Grand Cinema', ticket_url:'https://example.org/saturday'},
];
const queued_posts = [{...official_schedule[0], start_time:'20:00'}];
const check_fields = ['start_time','venue','ticket_url'];
const example_findings = [];
for (const expected of official_schedule) {
  const queued = queued_posts.find(row => row.event_id === expected.event_id);
  if (!queued) {
    example_findings.push({event_id:expected.event_id, issue:'missing_from_queue'});
    continue;
  }
  for (const field of check_fields) {
    if (expected[field] !== queued[field]) example_findings.push({
      event_id:expected.event_id, issue:'changed_field', field,
      official:expected[field], queued:queued[field],
    });
  }
}
return [{json:{source:'built_in_example', batch:{official_schedule,queued_posts,check_fields},
  example_findings}}];

const items = $input.all();
if (items.length !== 1) throw new Error('Group one official schedule and one queue into one input item per batch.');
return [{json:{source:'scheduler', batch:items[0].json}}];

const {source,batch,example_findings} = $input.first().json;
const allowed = ['start_time','venue','ticket_url'];
const fields = batch.check_fields === undefined ? allowed : batch.check_fields;
if (!Array.isArray(fields) || !fields.length || fields.length > allowed.length ||
    fields.some(f => !allowed.includes(f)) || new Set(fields).size !== fields.length)
  throw new Error('check_fields must contain unique choices from start_time, venue and ticket_url.');
if (batch.lookup_price !== undefined && typeof batch.lookup_price !== 'boolean')
  throw new Error('lookup_price must be true or false.');
function rows(data, name, official) {
  if (!Array.isArray(data) || data.length > 5000 || (official && !data.length))
    throw new Error(name + ' must be an array of up to 5,000 records; the official schedule must have at least one.');
  return data.map((row,i) => {
    if (!row || Array.isArray(row) || typeof row !== 'object' ||
        typeof row.event_id !== 'string' || !row.event_id.trim())
      throw new Error(name + ' row ' + (i+1) + ' needs a nonempty string event_id.');
    const selected = {event_id:row.event_id};
    for (const field of fields) {
      if (row[field] === undefined && !official) continue;
      if (typeof row[field] !== 'string' || (official && !row[field].trim()))
        throw new Error(name + ' row ' + (i+1) + ' needs a text value for ' + field + '.');
      selected[field] = row[field];
    }
    return selected;
  });
}
const official = rows(batch.official_schedule,'official_schedule',true);
const queue = rows(batch.queued_posts,'queued_posts',false);
const job = {source:{format:'json',data:official},target:{format:'json',data:queue},
  key:{source:'event_id',target:'event_id'},
  fields:fields.map(f=>({source:f,target:f,type:'exact'}))};
// Measure UTF-8 bytes with room for the maximum-length private request key.
const wire = JSON.stringify({job,request_key:'x'.repeat(128)});
let bytes = 0;
for (const char of wire) {
  const cp=char.codePointAt(0);
  bytes += cp<=127 ? 1 : cp<=2047 ? 2 : cp<=65535 ? 3 : 4;
  if (bytes>1000000) throw new Error('The encoded job exceeds the 1,000,000-byte comparison limit.');
}
const checkout = {
  endpoint:'https://botsnacks-testnet-api.cozah.chatgpt.site/api/v1/verify-transform', method:'POST',
  scheme:'exact', network:'eip155:84532', asset:'0x036CbD53842c5426634e7929541eC2318f3dCF7e',
  pay_to:'0x90b363b82bbffc5552d6635c8af959348117a7f3', max_amount_atomic:'30000',
  price:'0.03 test USDC per completed eligible comparison', price_check:'not_requested',
  buyer_instructions:'https://github.com/cozah123/botsnacks-csv-to-json/blob/150b40511abc0ace3f7b22892a506b069affeba5/SKILL.md#javascript-buyer'
};
return [{json:{
  status:source==='built_in_example'?'example_preview':'prepared_for_buyer',
  publish_ready:false, lookup_price:batch.lookup_price===true,
  counts:{official:official.length,queued:queue.length},
  ...(source==='built_in_example'?{example_findings}:{}), job, checkout
}}];

const prepared = $('Prepare comparison').first().json;
const {body,statusCode} = $input.first().json;
const expected = prepared.checkout;
const offers = body?.accepts;
const offer = Array.isArray(offers) && offers.length===1 ? offers[0] : null;
const matches = statusCode===402 && body?.x402Version===2 && body?.resource?.url===expected.endpoint &&
  offer?.scheme===expected.scheme && offer?.network===expected.network &&
  offer?.amount===expected.max_amount_atomic && typeof offer?.asset==='string' &&
  offer.asset.toLowerCase()===expected.asset.toLowerCase() && typeof offer.payTo==='string' &&
  offer.payTo.toLowerCase()===expected.pay_to &&
  (offer.extra?.assetTransferMethod === undefined || offer.extra.assetTransferMethod==='eip3009');
return [{json:{...prepared,status:matches?'price_confirmed':'hold_price_unverified',
  checkout:{...expected,price_check:matches?'verified':'unverified'}, publish_ready:false}}];
